mapper.select:
SELECT so_no, customer_id, operator_id, order_date, delivery_place, status, remark
FROM sale_order
WHERE so_no = #{soNo}

mapper.update:
UPDATE sale_order
SET customer_id    = #{customerId},
    order_date     = #{orderDate},
    delivery_place = #{deliveryPlace},
    remark         = #{remark}
WHERE so_no = #{soNo}

UPDATE sale_order
SET status = #{status}
WHERE so_no = #{soNo}
